 public void create(Long kid,Long vid,String ad,String soyad,boolean hekim){jdbc.queryForList("SELECT * FROM public.fn_personal_yarat(p_klinika_id=>:kid,p_vezife_id=>:vid,p_ad=>:ad,p_soyad=>:soyad,p_hekimdir=>:hekim,p_yaradan_personal_id=>NULL)",new MapSqlParameterSource().addValue("kid",kid).addValue("vid",vid).addValue("ad",ad.trim()).addValue("soyad",soyad.trim()).addValue("hekim",hekim));}
